/// und für die Prüfpunkte/Schritte der Ersteinrichtung – in allen 17 Sprachen.
/// Reihenfolge je Eintrag: de, en, fr, es, pt, ru, ja, zh, nl, af, pl, cs, sk, hu, ko, hi, ta
enum GS {
    static func t(_ key: String, _ lang: AppLanguage) -> String {
        guard let row = table[key] else { return key }
        let i = AppLanguage.allCases.firstIndex(of: lang) ?? 1
        return i < row.count ? row[i] : row[1]
    }

    /// Prüfpunkt-Titel der Ersteinrichtung (id aus ssccc_setup.py) übersetzen.
    static func checkTitle(_ id: String, fallback: String, _ lang: AppLanguage) -> String {
        table["chk_\(id)"] != nil ? t("chk_\(id)", lang) : fallback
    }

    /// Einrichtungsschritt (deutscher Titel aus ssccc_setup.py) übersetzen.
    static func stepTitle(_ german: String, _ lang: AppLanguage) -> String {
        let key = stepKeys[german] ?? ""
        return key.isEmpty ? german : t(key, lang)
    }

